import json
from pathlib import Path
R=Path.cwd();O=R/'outputs/expanded/mcgregor';DATA=[]
for folder in ['pilot','expansion','expansion_extra']:
 B=O/folder
 for sample in json.load(open(B/'manifest.json')):
  cid=sample['anonymous_id'];DATA.append({'folder':folder,'sample':sample,'label':json.load(open(B/'labels'/f'{cid}.json'))})
summary=json.load(open(O/'four_bout/bout_summary.json'));measures=json.load(open(O/'four_bout/quiet_projection_measurements.json'));dense=[]
for p in (O/'dense_check/labels').glob('*.json'):dense.append({**json.load(open(p)), 'id':p.stem})
design=json.load(open(O/'dense_check/registered_design.json'))
blob=json.dumps({'windows':DATA,'summary':summary,'measures':measures,'dense':dense,'denseDesign':design},separators=(',',':')).replace('<','\\u003c')
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>McGregor · Four-bout film room</title><style>
:root{--arena:#102f45;--steel:#1d4860;--mist:#f4f7fa;--cyan:#22d3ee;--coral:#fb7185;--ink:#17384c;--muted:#667985}*{box-sizing:border-box}body{margin:0;background:var(--mist);color:var(--ink);font:15px/1.55 'Avenir Next',Avenir,Arial,sans-serif}button,select,input{font:inherit}button,select{border:1px solid #9ab0bc;border-radius:5px;padding:9px 12px;background:white;color:var(--ink);cursor:pointer}button:hover,select:hover{border-color:var(--cyan)}:focus-visible{outline:3px solid var(--coral);outline-offset:3px}a{color:#0d607a;text-underline-offset:3px}header{background:var(--arena);color:white;padding:35px max(24px,calc((100vw - 1340px)/2));border-bottom:7px solid var(--cyan)}.eyebrow{font:12px Menlo,Consolas,monospace;letter-spacing:2px;color:#a8deeb;text-transform:uppercase}h1{font:clamp(42px,6vw,78px)/.95 Impact,'Arial Narrow',sans-serif;letter-spacing:1px;font-weight:400;margin:16px 0}header p{max-width:820px;color:#d0e0e9;margin:18px 0 0}.grade{display:inline-block;border-left:3px solid var(--coral);padding:8px 15px;margin-top:24px;font-weight:600}main{max-width:1390px;margin:auto;padding:30px 24px 70px}h2{font:30px/1.15 'Arial Narrow',Arial,sans-serif;margin:0 0 15px}h3{margin:0 0 8px;font-size:20px}.section{margin-top:46px}.timeline{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border:1px solid #b9cbd5;margin-bottom:28px;background:#e7eff4}.timeline button{border:0;border-right:1px solid #b9cbd5;background:transparent;border-radius:0;text-align:left;padding:15px}.timeline strong{font:30px Impact,'Arial Narrow',sans-serif;font-weight:400;display:block}.timeline small{color:var(--muted)}.players{display:grid;grid-template-columns:1fr 1fr;gap:18px}.player{background:var(--arena);color:white;border-radius:8px;overflow:hidden}.player-head{display:flex;justify-content:space-between;align-items:center;padding:13px 15px;gap:15px}.player-head select{background:var(--steel);color:white;border-color:#5a8298;min-width:180px}.side{font:12px Menlo,monospace;letter-spacing:1px}.left .side{color:var(--cyan)}.right .side{color:var(--coral)}video{width:100%;display:block;background:black;aspect-ratio:960/590}.player p{padding:12px 15px;margin:0;color:#d2e0e7;font-size:13px;min-height:70px}.transport{display:flex;align-items:center;gap:11px;flex-wrap:wrap;padding:16px 0;border-bottom:1px solid #b9cbd5}.transport .play{background:var(--arena);color:white;min-width:135px}.transport input{flex:1;min-width:130px;accent-color:#0d768a}.clock{font:14px Menlo,monospace;min-width:75px}.small{font-size:13px;color:var(--muted)}.note{border-left:3px solid #8ba5b4;padding:10px 15px;background:#e8f0f5;margin:16px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;background:white}th,td{padding:12px 13px;border-bottom:1px solid #d2dfe6;text-align:left;vertical-align:top}th{font:12px Menlo,monospace;text-transform:uppercase;color:#526f80;background:#e4edf3}td .num{font:19px Menlo,monospace}figure{margin:20px 0;background:white;padding:14px;border:1px solid #d2dfe6;border-radius:8px}figure img{display:block;width:100%;max-width:1200px;margin:auto}figcaption{color:var(--muted);font-size:13px;margin:13px 4px}.split-notes{display:grid;grid-template-columns:1fr 1fr;gap:20px}.filters{display:flex;gap:12px;flex-wrap:wrap;margin:15px 0}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{background:white;border:1px solid #cbdbe4;border-radius:8px;overflow:hidden}.card-top{padding:15px}.card-top p{font-size:13px;color:var(--muted);margin:7px 0}.card img{width:100%;display:block}.card details{padding:12px 15px;border-top:1px solid #e0e9ee}.card summary{cursor:pointer;font-size:14px;font-weight:600}.card details p{font-size:13px}.card pre{font:12px/1.5 Menlo,monospace;white-space:pre-wrap;max-height:420px;overflow:auto}.tag{display:inline-block;border:1px solid #b7ccd8;border-radius:3px;font:11px Menlo,monospace;padding:3px 6px;margin-right:4px}.limitation{font-size:14px;line-height:1.7}.footer{margin-top:35px;padding-top:20px;border-top:1px solid #b7ccd8}.pill{background:#dcedf5;display:inline-block;padding:4px 8px;border-radius:4px;font-size:12px}.status{font:13px Menlo,monospace;color:var(--muted)}@media(max-width:950px){.cards{grid-template-columns:1fr 1fr}.player-head{align-items:flex-start;flex-direction:column}.split-notes{grid-template-columns:1fr}}@media(max-width:650px){main{padding:22px 13px}.players,.cards{grid-template-columns:1fr}.timeline{grid-template-columns:1fr 1fr}.timeline button{border-bottom:1px solid #b9cbd5}header{padding:28px 20px}.transport button{padding:8px}.player p{min-height:0}.player-head{flex-direction:row}h2{font-size:25px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style></head><body><header><div class="eyebrow">McGregor movement evidence / four-bout film room</div><h1>Four bouts,<br>frame by frame.</h1><p>Compare native standing footage, then inspect the observations and visibility limits. The same fighter appears across four opponent contexts; these samples reveal useful movement examples.</p><div class="grade">Useful comparison · No proven career trend</div></header><main>
<div class="timeline" id="timeline"></div><p class="small">2012 is the earliest downloaded footage in this study, not his career debut. 2021 is the latest downloaded footage here, not the end of his career.</p>
<section aria-labelledby="pair-title"><h2 id="pair-title">Choose two bouts. Watch the feet.</h2><div class="players"><article class="player left"><div class="player-head"><span class="side">LEFT BOUT</span><select id="leftBout" aria-label="Left bout"></select></div><video id="leftVideo" preload="metadata" playsinline muted controls></video><p id="leftInfo"></p></article><article class="player right"><div class="player-head"><span class="side">RIGHT BOUT</span><select id="rightBout" aria-label="Right bout"></select></div><video id="rightVideo" preload="metadata" playsinline muted controls></video><p id="rightInfo"></p></article></div><div class="transport"><button class="play" id="playPair">Play both</button><button id="back">−0.25s</button><button id="forward">+0.25s</button><input id="timeSlider" type="range" min="0" max="7.75" step="0.05" value="0" aria-label="Shared relative clip time"><output class="clock" id="pairClock">0.00s</output><select id="speed" aria-label="Playback speed"><option value="1">1× speed</option><option value="0.5">0.5× speed</option><option value="0.25">0.25× speed</option></select><button id="reset">Reset both</button></div><p class="small">Shared controls synchronize relative time within two independent 8-second windows. They show different exchanges, opponents and camera views; the timing alignment has no tactical meaning. Individual video controls remain available.</p><p id="playStatus" class="status" aria-live="polite"></p></section>
<section class="section"><h2>What was actually observable?</h2><p>28 labeled windows are nested in <strong>four bouts</strong>. Punches, kicks and bounce cycles below are reported visible lower bounds at 4Hz. They are not full-bout totals, proven absences, or independent-frame statistics.</p><div class="table-wrap" id="exposure"></div><div class="note">A cropped foot, unresolved clothing identity or hidden action stays unknown. Empty observation arrays under poor visibility do not become zero. The original systematic broadcast samples and later phase-selected standing supplements retain separate provenance.</div></section>
<section class="section"><h2>Check the projection against the pixels.</h2><figure><a href="four_bout/validated-projection-comparison.jpg"><img src="four_bout/validated-projection-comparison.jpg" alt="Four native quiet-standing anchors with accepted ankle-span and right shoulder-to-ankle lines, exact source timestamps, view and heel estimates"></a><figcaption>Cyan: projected ankle span. Coral: accepted right shoulder-to-right ankle scale. Only visually accepted candidate landmarks enter this ratio. The back, three-quarter and front views differ, so these examples cannot be averaged into a career direction.</figcaption></figure><div class="split-notes"><div><h3>A visible scale, with limits</h3><p>Hip centers could not be identified through the shorts. Hip-based stance, torso lean, forces and weight distribution remain withheld. The displayed shoulder-to-ankle scale is an image-plane proxy, not anatomical height or 3D stance width.</p><p>Within the sampled anchors, 2018 right-side ratios range from 0.332 to 0.522 and 2021 from 0.322 to 0.538. A simple monotonic stance narrative does not survive that variation and the different views.</p></div><div><h3>Momentary heel observations</h3><p>Some 2013 and 2021 native frames show an apparently raised heel. One 2018 frame is visually labeled both flat. These are model image estimates of specific moments, not measurements of contact force or bodyweight.</p><p>Face and wrist measures are retained only where their landmarks were individually accepted. Lead and rear hand roles are not inferred.</p></div></div><details><summary>Inspect all accepted quiet-anchor measures and rejected landmarks</summary><pre id="measureData" style="white-space:pre-wrap;max-height:500px;overflow:auto"></pre><a href="adaptive/validated_measurements.json">Original-bout visual checks</a> · <a href="adaptive_expansion/validated_measurements.json">Added-bout visual checks</a></details></section>
<section class="section"><h2>Does denser sampling change the observations?</h2><p>A fresh, independent annotator sees the same 8-second windows at 8Hz, without the original counts or an expected era/style direction. Changes expose sampling and label sensitivity; agreement is not human ground truth.</p><div id="sensitivity"></div></section>
<section class="section"><h2>Open any of the 28 evidence windows.</h2><p>Each window keeps full native frames, timed phase/action/movement labels, clothing anchors and uncertainty. Replays, breaks, clinches and ground footage are retained as exclusions rather than replaced with convenient examples.</p><div class="filters"><select id="boutFilter" aria-label="Filter evidence by bout"><option value="">All four bouts</option></select><select id="phaseFilter" aria-label="Filter evidence by phase"><option value="">All phases</option><option>standing</option><option>clinch</option><option>ground</option><option>break</option><option>nonfight</option></select><span class="status" id="shown"></span></div><div class="cards" id="cards"></div></section>
<section class="section limitation"><h2>How far can these findings travel?</h2><p>The useful result is a reviewable comparison of selected movement examples and model observations. Four opponents, uneven rounds/ranges/pressure, different broadcast views and two sampling designs prevent a career-style conclusion. Names, faces and clothing remain readable, so prompt blinding to date and expected direction is incomplete.</p><p>Camera compensation uses person-masked background optical flow and robust fits to flag unstable camera estimates. Those fits do not establish foot displacement or bounce. All annotations and image reviews use the same model family, without new training; no motion-capture or human gold truth is claimed.</p></section><div class="footer"><a href="four_bout/findings.txt">Full findings</a> · <a href="four_bout/window_summary.csv">Exposure roster</a> · <a href="four_bout/completed_roster.json">All completed labels</a> · <a href="four_bout/quiet_projection_measurements.json">Projected measures</a> · <a href="four_bout/camera_flow_diagnostic.json">Camera diagnostics</a> · <a href="protocol.txt">Study protocol</a> · <a href="../index.html">Expanded MMA review</a><p class="small">Source footage is preserved. Superseded masking/anchor attempts remain in the audit history and are excluded from these corrected results.</p></div></main>
<script>const DATA=__DATA__;
const BOUTS=[{id:'obgm6JNtyVo',year:'2012',name:'Cage Warriors',start:250,target:'Navy shorts · yellow gloves · red tape',url:'obgm6JNtyVo'},{id:'BCOy-PG8EIw',year:'2013',name:'Holloway',start:223,target:'Black/green shorts · red tape',url:'BCOy-PG8EIw'},{id:'khabib-mcgregor',year:'2018',name:'Nurmagomedov',start:675,target:'Green shorts · blue tape',url:'JuBBIJ7adjM'},{id:'6yu2AWK4rxo',year:'2021',name:'Poirier II',start:596,target:'Green/olive shorts · blue tape',url:'6yu2AWK4rxo'}];
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const bout=id=>BOUTS.find(b=>b.id===id),opts=BOUTS.map(b=>`<option value="${b.id}">${b.year} · ${b.name}</option>`).join('');$('leftBout').innerHTML=opts;$('rightBout').innerHTML=opts;$('rightBout').value=BOUTS[3].id;$('boutFilter').innerHTML+=opts;$('timeline').innerHTML=BOUTS.map(b=>`<button data-bout="${b.id}" title="Filter evidence to ${b.year}"><strong>${b.year}</strong>${b.name}<br><small>${b.target}</small></button>`).join('');
const lv=$('leftVideo'),rv=$('rightVideo');let playing=false,changing=false;function pause(){playing=false;lv.pause();rv.pause();$('playPair').textContent='Play both'}function seek(t){pause();const value=Math.max(0,Math.min(7.75,t));for(const v of[lv,rv])if(v.readyState>=1)v.currentTime=value;$('timeSlider').value=value;$('pairClock').value=value.toFixed(2)+'s'}function setVideo(side){pause();const b=bout($(side+'Bout').value),v=$(side+'Video');changing=true;v.src=`four_bout/clips/${b.year}-native-standing.mp4`;v.load();$(side+'Info').innerHTML=`${esc(b.target)}<br>Source ${b.start}–${b.start+8}s · <a style="color:#a8deeb" href="https://www.youtube.com/watch?v=${b.url}&t=${b.start}s" target="_blank" rel="noreferrer">Official source footage</a>`;v.onloadedmetadata=()=>{v.currentTime=0;changing=false;$('timeSlider').value=0;$('pairClock').value='0.00s'};}setVideo('left');setVideo('right');$('leftBout').onchange=()=>{setVideo('left');seek(0)};$('rightBout').onchange=()=>{setVideo('right');seek(0)};$('playPair').onclick=async()=>{if(playing){pause();return}if(lv.readyState<1||rv.readyState<1){$('playStatus').textContent='Wait for both clips to load, then play.';return}const t=lv.currentTime>=7.75?0:lv.currentTime;rv.currentTime=t;lv.currentTime=t;for(const v of[lv,rv])v.playbackRate=+$('speed').value;try{await Promise.all([lv.play(),rv.play()]);playing=true;$('playPair').textContent='Pause both';$('playStatus').textContent='Shared relative time; independent exchanges.'}catch(e){pause();$('playStatus').textContent='Playback could not start. Use the individual video controls or open the native clips.'}};$('timeSlider').oninput=e=>seek(+e.target.value);$('back').onclick=()=>seek(lv.currentTime-.25);$('forward').onclick=()=>seek(lv.currentTime+.25);$('reset').onclick=()=>seek(0);$('speed').onchange=()=>{for(const v of[lv,rv])v.playbackRate=+$('speed').value};for(const v of[lv,rv]){v.onended=pause;v.onerror=()=>{$('playStatus').textContent='A clip could not load. Open this viewer through the local review server, or use the native video links below.'}}function tick(){if(playing){if(lv.currentTime>=7.75){pause()}else if(rv.readyState>=2&&Math.abs(rv.currentTime-lv.currentTime)>.10)rv.currentTime=lv.currentTime;$('timeSlider').value=lv.currentTime;$('pairClock').value=lv.currentTime.toFixed(2)+'s'}requestAnimationFrame(tick)}tick();
$('exposure').innerHTML=`<table><thead><tr><th>Bout</th><th>Windows</th><th>Identifiable standing</th><th>Feet-visible estimate</th><th>Quiet-standing estimate</th><th>Punch / kick lower bounds</th><th>Reported bounce cycles</th></tr></thead><tbody>${DATA.summary.bouts.map(s=>{const b=bout(s.source),a=s.attempt_reported_lower_bounds;return`<tr><td><strong>${b.year} · ${b.name}</strong></td><td>${s.windows_labeled}</td><td>${s.identifiable_standing_seconds_estimate.toFixed(2)}s</td><td>${s.feet_visible_seconds_estimate.toFixed(2)}s</td><td>${s.quiet_standing_seconds_estimate.toFixed(2)}s</td><td><span class="num">${a.punch} / ${a.kick}</span></td><td>${s.bounce_cycles_reported_lower_bound}<br><small>${s.bounce_observable_windows} observable windows</small></td></tr>`}).join('')}</tbody></table>`;$('measureData').textContent=JSON.stringify(DATA.measures,null,2);
function counts(events){return ['punch','kick'].map(type=>events.filter(e=>e.type===type&&['high','medium'].includes(e.certainty)).length)}function sensitivity(){const rows=DATA.denseDesign.cases.map(c=>{const original=DATA.windows.find(w=>w.sample.anonymous_id===c.base_interval&&w.folder===c.base_folder),dense=DATA.dense.find(d=>d.id===c.id),b=bout(c.source),old=counts(original.label.strike_attempts),now=dense?counts(dense.target_attempts):null;return`<tr><td>${b.year} · ${b.name}<br><small>source ${c.start}s / ${c.base_interval}</small></td><td>${old[0]} / ${old[1]}</td><td>${now?now[0]+' / '+now[1]:'Pending'}</td><td>${dense?`<details><summary>Inspect denser action-response labels</summary><pre style="white-space:pre-wrap;max-height:400px;overflow:auto">${esc(JSON.stringify(dense,null,2))}</pre></details>`:'Independent review still running'}</td></tr>`});$('sensitivity').innerHTML=`<p class="status">${DATA.dense.length} of 4 independent denser reviews complete.</p><div class="table-wrap"><table><thead><tr><th>Same interval</th><th>4Hz punch / kick</th><th>8Hz punch / kick</th><th>Evidence</th></tr></thead><tbody>${rows.join('')}</tbody></table></div><p class="small">No count is silently replaced. Sampling density and fresh annotation both change, so disagreements cannot be attributed to frame rate alone.</p>`}sensitivity();
function renderCards(){const filter=$('boutFilter').value,phase=$('phaseFilter').value,rows=DATA.windows.filter(w=>(!filter||w.sample.source===filter)&&(!phase||w.label.phases.some(p=>p.phase===phase))).sort((a,b)=>BOUTS.findIndex(x=>x.id===a.sample.source)-BOUTS.findIndex(x=>x.id===b.sample.source)||a.sample.start-b.sample.start);$('shown').textContent=rows.length+' of 28 windows';$('cards').innerHTML=rows.map(w=>{const s=w.sample,l=w.label,b=bout(s.source),id=s.anonymous_id,unresolved=id==='X06';return`<article class="card"><div class="card-top"><strong>${b.year} · ${id} · source ${s.start}s</strong><p>${l.phases.map(p=>`<span class="tag">${esc(p.phase)}</span>`).join('')}</p><p>Identity: ${unresolved?'unresolved anchor, not physical absence':esc(l.target_identity_visibility)} · live ${esc(l.live_fight)} · replay ${esc(l.likely_replay)}</p><p>${esc(l.target_clothing)}</p></div><a href="${w.folder}/native/${id}-00.jpg"><img loading="lazy" src="${w.folder}/native/${id}-00.jpg" alt="${b.year} ${id}, source ${s.start} seconds, full native frame"></a><details><summary>Timed movement, guard and action observations</summary><pre>${esc(JSON.stringify({phases:l.phases,strike_attempts:l.strike_attempts,footwork:l.footwork,guard:l.guard_observations,stance:l.stance_observations,quiet:l.usable_quiet_standing_intervals,camera:l.camera,uncertainties:l.uncertainties},null,2))}</pre><a href="${w.folder}/labels/${id}.json">Original corrected label</a> · <a href="${w.folder}/audit/${id}.metadata.json">Tool-free run metadata</a></details><details><summary>Inspect all timestamped input sheets</summary>${[0,1,2,3].map(i=>`<a href="${w.folder}/evidence/${id}-${String(i).padStart(2,'0')}.jpg"><img loading="lazy" src="${w.folder}/evidence/${id}-${String(i).padStart(2,'0')}.jpg" alt="${id} quarter-second frame sheet ${i+1}"></a>`).join('')}</details><details><summary>Full native anchor frames</summary>${['16','31'].map(n=>`<a href="${w.folder}/native/${id}-${n}.jpg"><img loading="lazy" src="${w.folder}/native/${id}-${n}.jpg" alt="${id} native anchor ${n}"></a>`).join('')}</details></article>`}).join('')}$('boutFilter').onchange=renderCards;$('phaseFilter').onchange=renderCards;document.querySelectorAll('[data-bout]').forEach(btn=>btn.onclick=()=>{$('boutFilter').value=btn.dataset.bout;renderCards();$('boutFilter').scrollIntoView({block:'center',behavior:'auto'})});renderCards();
</script></body></html>'''
(O/'index.html').write_text(html.replace('__DATA__',blob));(O/'four_bout/index.html').write_text('<!doctype html><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=../index.html"><title>Four-bout film room</title><a href="../index.html">Open the four-bout film room</a>');print('Built viewer',len(DATA),'windows',len(dense),'dense checks')
